(67,'inventory_items',$columns$box_code TEXT NOT NULL UNIQUE, customer_company_id UUID NOT NULL REFERENCES customer_companies(id) ON DELETE RESTRICT, warehouse_id UUID NOT NULL REFERENCES warehouses(id) ON DELETE RESTRICT, storage_contract_id UUID REFERENCES storage_contracts(id) ON DELETE RESTRICT, contents TEXT NOT NULL DEFAULT '', quantity NUMERIC(18,4) NOT NULL CHECK(quantity>=0), status TEXT NOT NULL DEFAULT 'expected' CHECK(status IN ('expected','received','reserved','dispatched')), version INTEGER NOT NULL DEFAULT 1$columns$),
