(71,'trucks',$columns$code TEXT NOT NULL UNIQUE, plate TEXT NOT NULL, country_code CHAR(2) NOT NULL CHECK(country_code ~ '^[A-Z]{2}$'), truck_type TEXT NOT NULL, max_kg NUMERIC(18,4) CHECK(max_kg>0), length_cm NUMERIC(18,4), width_cm NUMERIC(18,4), height_cm NUMERIC(18,4), active BOOLEAN NOT NULL DEFAULT true, version INTEGER NOT NULL DEFAULT 1$columns$),
