(75,'delivery_proofs',$columns$delivery_order_id UUID NOT NULL REFERENCES delivery_orders(id) ON DELETE RESTRICT, file_id UUID NOT NULL REFERENCES files(id) ON DELETE RESTRICT, recipient_name TEXT NOT NULL, delivered_at TIMESTAMPTZ NOT NULL$columns$),
(76,'feedback',$columns$booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id) ON DELETE RESTRICT, customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), ratings JSONB NOT NULL DEFAULT '{}', comment TEXT NOT NULL DEFAULT ''$columns$),
(77,'inquiries',$columns$code TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES customers(id) ON DELETE RESTRICT, assignee_id UUID REFERENCES users(id) ON DELETE RESTRICT, email TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('website','email','phone','staff','whatsapp')), status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','assigned','quoted','closed')), summary TEXT NOT NULL, due_at TIMESTAMPTZ, version INTEGER NOT NULL DEFAULT 1$columns$),
(78,'quotations',$columns$code TEXT NOT NULL UNIQUE, customer_company_id UUID NOT NULL REFERENCES customer_companies(id) ON DELETE RESTRICT, inquiry_id UUID REFERENCES inquiries(id) ON DELETE RESTRICT, booking_id UUID REFERENCES bookings(id) ON DELETE RESTRICT, currency CHAR(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT CHECK(currency ~ '^[A-Z]{3}$'), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','sent','accepted','declined','expired')), valid_until TIMESTAMPTZ NOT NULL, amount NUMERIC(18,4) NOT NULL CHECK(amount>=0), version INTEGER NOT NULL DEFAULT 1$columns$),
(79,'quotation_lines',$columns$quotation_id UUID NOT NULL REFERENCES quotations(id) ON DELETE RESTRICT, product_service_id UUID REFERENCES products_services(id) ON DELETE RESTRICT, selling_rate_id UUID REFERENCES selling_rates(id) ON DELETE RESTRICT, description TEXT NOT NULL, amount NUMERIC(18,4) NOT NULL CHECK(amount>=0), currency CHAR(3) NOT NULL REFERENCES currencies(code) ON DELETE RESTRICT CHECK(currency ~ '^[A-Z]{3}$')$columns$),
(80,'employees',$columns$user_id UUID NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT, employee_code TEXT NOT NULL UNIQUE, department TEXT NOT NULL DEFAULT '', job_title TEXT NOT NULL DEFAULT '', start_date DATE, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','leave','ended')), version INTEGER NOT NULL DEFAULT 1$columns$),
(81,'employee_documents',$columns$employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE RESTRICT, file_id UUID NOT NULL REFERENCES files(id) ON DELETE RESTRICT, kind TEXT NOT NULL, expires_at TIMESTAMPTZ$columns$),
(82,'scheduler_runs',$columns$job_key TEXT NOT NULL, bucket TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','completed','failed')), error_code TEXT, completed_at TIMESTAMPTZ, UNIQUE(job_key,bucket)$columns$),
(83,'backup_runs',$columns$backup_date DATE NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('running','completed','failed')), manifest_path TEXT, manifest_sha256 CHAR(64), error_code TEXT, completed_at TIMESTAMPTZ$columns$)
 ) AS definitions(ordinal,name,columns) ORDER BY ordinal LOOP
  EXECUTE format('CREATE TABLE %I (%s, %s)',definition.name,common,definition.columns);
