CREATE UNIQUE INDEX exchange_rates_one_active_day ON exchange_rates(rule_id,rate_date) WHERE status='active' AND deleted_at IS NULL;
ALTER TABLE rate_confirmations ADD CONSTRAINT rate_confirmation_previous_fk FOREIGN KEY(previous_id) REFERENCES exchange_rates(id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX customer_company_single_owner ON customer_memberships(customer_company_id) WHERE role='owner' AND status='active' AND deleted_at IS NULL;
CREATE UNIQUE INDEX users_legacy_customer_unique ON customers(user_id) WHERE deleted_at IS NULL;
CREATE FUNCTION ukr_touch_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=clock_timestamp(); RETURN NEW; END $$;
CREATE FUNCTION ukr_append_only() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only history cannot be changed' USING ERRCODE='23514'; END $$;
DO $$
DECLARE tbl TEXT; col RECORD;
BEGIN
 FOREACH tbl IN ARRAY ARRAY['users','roles','permissions','role_permissions','user_roles','currencies','companies','customers','customer_companies','customer_memberships','customer_invitations','warehouses','user_warehouses','user_currencies','accounts','products_services','services','routes','themes','user_preferences','settings','sessions','otp_codes','auth_limits','audit_log','email_templates','email_outbox','mail_accounts','mail_account_users','mail_messages','exchange_rate_rules','rate_confirmations','exchange_rates','tax_rates','bookings','booking_items','consolidations','consolidation_bookings','shipments','shipment_events','files','goods_in_receipts','goods_in_photos','documents','task_rules','workflow_events','approvals','approval_steps','booking_status_events','tasks','task_comments','task_events','invoices','invoice_lines','payments','payment_proofs','payment_orders','receipts','journal_entries','journal_lines','purchase_rates','selling_rates','delivery_rates','purchase_rate_rules','purchase_invoices','purchase_invoice_bookings','storage_contracts','inventory_items','fulfilment_orders','fulfilment_order_items','credit_lines','trucks','truck_documents','drivers','delivery_orders','delivery_proofs','feedback','inquiries','quotations','quotation_lines','employees','employee_documents','scheduler_runs','backup_runs'] LOOP
   EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION ukr_touch_updated_at()',tbl||'_touch',tbl);
   FOR col IN SELECT column_name FROM information_schema.columns WHERE table_schema=current_schema() AND table_name=tbl AND (column_name='created_by' OR column_name LIKE '%\_id' ESCAPE '\' OR column_name IN ('status','state','code','email','currency','base_currency','quote_currency','legacy_token_hash') OR data_type IN ('date','timestamp with time zone','timestamp without time zone')) LOOP
     EXECUTE format('CREATE INDEX %I ON %I (%I)',left(tbl||'_'||col.column_name||'_idx',63),tbl,col.column_name);
   END LOOP;
 END LOOP;
 FOREACH tbl IN ARRAY ARRAY['audit_log','approval_steps','task_events','booking_status_events','shipment_events'] LOOP
   EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION ukr_append_only()',tbl||'_immutable',tbl);
 END LOOP;
END $$;
